import { PACKAGE_NAME } from '../constants.js';
import { getPrimaryKey } from '../sql-generator/utils/ast-helpers.js';
import { getClientExportName } from '../db/type-generator.js';
import { toRouteBasePath, toRouteFileName, toRouteImportName, } from '../api/utils/route-naming.js';
import { toModelConstantPrefix } from './utils/api-fields.js';
import { hasPolicies } from './utils/policy.js';
import { isViewRestEnabled, normalizeViewRest } from './utils/rest.js';
export class ViewRouteGenerator {
    view;
    schema;
    constructor(view, schema) {
        this.view = view;
        this.schema = schema;
    }
    generate() {
        const rest = normalizeViewRest(this.view);
        const operations = rest.operations;
        if (operations.size === 0) {
            return null;
        }
        const needsPk = operations.has('get');
        const primaryKey = getPrimaryKey(this.view);
        if (needsPk && !primaryKey) {
            throw new Error(`View ${this.view.name} has no primary key`);
        }
        const clientKey = getClientExportName(this.view.name);
        const pathParams = primaryKey?.fields.map((field) => `:${field}`).join('/') ?? '';
        const whereFromParams = primaryKey?.fields.map((field) => `${field}: params.${field}`).join(', ') ?? '';
        const paramSchemaName = `${this.view.name}ParamSchema`;
        const listQuerySchemaName = `${this.view.name}ListQuerySchema`;
        const getQuerySchemaName = `${this.view.name}GetQuerySchema`;
        const viewHasPolicies = hasPolicies(this.view);
        const constantPrefix = toModelConstantPrefix(this.view.name);
        const needsValidateParam = operations.has('get');
        const needsValidateQuery = operations.has('list') || operations.has('get');
        const needsNotFound = operations.has('get');
        const needsBuildReadQuery = operations.has('list');
        const validateImports = [];
        if (needsValidateParam)
            validateImports.push('validateParam');
        if (needsValidateQuery)
            validateImports.push('validateQuery');
        const schemaImports = [];
        if (needsValidateParam)
            schemaImports.push(`  ${paramSchemaName},`);
        if (operations.has('list'))
            schemaImports.push(`  ${listQuerySchemaName},`);
        if (operations.has('get'))
            schemaImports.push(`  ${getQuerySchemaName},`);
        if (operations.has('list')) {
            schemaImports.push(`  ${constantPrefix}_LIST_QUERY_FIELDS,`);
            schemaImports.push(`  ${constantPrefix}_SORTABLE_FIELDS,`);
        }
        if (operations.has('list') || operations.has('get')) {
            schemaImports.push(`  ${constantPrefix}_INCLUDABLE_RELATIONS,`);
        }
        schemaImports.push(`  API_OMIT_FIELDS_BY_MODEL,`);
        schemaImports.push(`  API_RELATION_TARGETS,`);
        const handlerBlocks = [];
        if (operations.has('list')) {
            handlerBlocks.push(this.generateListRoute(clientKey, viewHasPolicies, listQuerySchemaName, constantPrefix));
        }
        if (operations.has('get')) {
            handlerBlocks.push(this.generateGetRoute(clientKey, pathParams, paramSchemaName, getQuerySchemaName, whereFromParams, viewHasPolicies));
        }
        const lines = [
            '// Auto-generated by ViewRouteGenerator. Do not edit manually.',
            "import { Hono } from 'hono';",
            `import type { AppEnv } from '${PACKAGE_NAME}/api/types';`,
        ];
        if (validateImports.length > 0) {
            lines.push(`import { ${validateImports.join(', ')} } from '${PACKAGE_NAME}/api/middleware/validate';`);
        }
        if (needsNotFound) {
            lines.push(`import { notFoundResponse } from '${PACKAGE_NAME}/api/middleware/errors';`);
        }
        if (needsBuildReadQuery) {
            lines.push(`import { buildReadQuery } from '${PACKAGE_NAME}/api/utils/read-query';`);
        }
        lines.push(`import { shapeResponse, shapeResponseMany } from '${PACKAGE_NAME}/api/utils/response-shape';`);
        if (viewHasPolicies) {
            lines.push(`import { assertPolicy, mergeWhere, resolvePolicyWhere } from '${PACKAGE_NAME}/api/auth/policy';`);
        }
        if (schemaImports.length > 0) {
            lines.push('import {');
            lines.push(...schemaImports);
            lines.push(`} from '../schemas/validation.js';`);
        }
        lines.push('', 'const router = new Hono<AppEnv>();', '');
        for (const block of handlerBlocks) {
            lines.push(...block, '');
        }
        lines.push('export default router;', '');
        return lines.join('\n');
    }
    getRouteFileName() {
        return toRouteFileName(this.view.name);
    }
    getRouteBasePath() {
        return toRouteBasePath(this.view.name);
    }
    generateListRoute(clientKey, viewHasPolicies, listQuerySchemaName, constantPrefix) {
        const listQueryBlock = [
            `  const query = c.req.valid('query');`,
            `  const { where, orderBy, take, skip } = buildReadQuery(`,
            `    query,`,
            `    ${constantPrefix}_LIST_QUERY_FIELDS,`,
            `    ${constantPrefix}_SORTABLE_FIELDS,`,
            `    ${constantPrefix}_INCLUDABLE_RELATIONS,`,
            `  );`,
        ];
        if (!viewHasPolicies) {
            return [
                `router.get('/', validateQuery(${listQuerySchemaName}), async (c) => {`,
                "  const db = c.get('db');",
                ...listQueryBlock,
                `  const rows = await db.${clientKey}.findMany({`,
                '    where,',
                '    orderBy,',
                '    take,',
                '    skip,',
                '  });',
                `  return c.json(shapeResponseMany(rows, '${this.view.name}', API_OMIT_FIELDS_BY_MODEL, API_RELATION_TARGETS));`,
                '});',
            ];
        }
        return [
            `router.get('/', validateQuery(${listQuerySchemaName}), async (c) => {`,
            "  const db = c.get('db');",
            "  const auth = c.get('auth');",
            `  const policy = assertPolicy('${this.view.name}', auth.role, 'select');`,
            '  const policyWhere = resolvePolicyWhere(policy, auth);',
            ...listQueryBlock,
            `  const rows = await db.${clientKey}.findMany({`,
            '    where: mergeWhere(where, policyWhere),',
            '    orderBy,',
            '    take,',
            '    skip,',
            '  });',
            `  return c.json(shapeResponseMany(rows, '${this.view.name}', API_OMIT_FIELDS_BY_MODEL, API_RELATION_TARGETS));`,
            '});',
        ];
    }
    generateGetRoute(clientKey, pathParams, paramSchemaName, getQuerySchemaName, whereFromParams, viewHasPolicies) {
        if (!viewHasPolicies) {
            return [
                `router.get('/${pathParams}', validateParam(${paramSchemaName}), validateQuery(${getQuerySchemaName}), async (c) => {`,
                "  const db = c.get('db');",
                "  const params = c.req.valid('param');",
                `  const row = await db.${clientKey}.findUnique({ ${whereFromParams} });`,
                '  if (!row) {',
                '    return notFoundResponse(c);',
                '  }',
                `  return c.json(shapeResponse(row, '${this.view.name}', API_OMIT_FIELDS_BY_MODEL, API_RELATION_TARGETS));`,
                '});',
            ];
        }
        return [
            `router.get('/${pathParams}', validateParam(${paramSchemaName}), validateQuery(${getQuerySchemaName}), async (c) => {`,
            "  const db = c.get('db');",
            "  const auth = c.get('auth');",
            "  const params = c.req.valid('param');",
            `  const policy = assertPolicy('${this.view.name}', auth.role, 'select');`,
            '  const policyWhere = resolvePolicyWhere(policy, auth);',
            `  const row = await db.${clientKey}.findFirst({ where: mergeWhere({ ${whereFromParams} }, policyWhere) });`,
            '  if (!row) {',
            '    return notFoundResponse(c);',
            '  }',
            `  return c.json(shapeResponse(row, '${this.view.name}', API_OMIT_FIELDS_BY_MODEL, API_RELATION_TARGETS));`,
            '});',
        ];
    }
}
export function generateViewRouteFiles(schema) {
    const files = new Map();
    for (const view of schema.views) {
        if (!isViewRestEnabled(view)) {
            continue;
        }
        const generator = new ViewRouteGenerator(view, schema);
        const content = generator.generate();
        if (content !== null) {
            files.set(generator.getRouteFileName(), content);
        }
    }
    return files;
}
export function getViewRouteMountEntries(schema) {
    return schema.views.filter(isViewRestEnabled).map((view) => {
        const basePath = toRouteBasePath(view.name);
        return {
            basePath,
            fileName: toRouteFileName(view.name),
            importName: toRouteImportName(basePath),
        };
    });
}
